    sort(order.begin(), order.end(), [&](int a, int b) {
        return P[a] < P[b];
    });

    int maxNodes = 2 * K + 5;
    vector<long long> val(maxNodes, 0), sum(maxNodes, 0);
    vector<int> parent(maxNodes, 0), F(maxNodes, 0);
    vector<vector<int>> children(maxNodes);

