        val[i] = P[i];
        sum[i] = P[i];
    }

    vector<int> dsu(K), sz(K), compNode(K, 0);
    vector<char> active(K, 0);

    auto find = [&](int x) {
        int r = x;
        while (dsu[r] != r) r = dsu[r];
        while (dsu[x] != x) {
            int p = dsu[x];
            dsu[x] = r;
            x = p;
        }
        return r;
    };

    auto unite = [&](int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (sz[ra] < sz[rb]) swap(ra, rb);
        dsu[rb] = ra;
        sz[ra] += sz[rb];
    };

    int nodeCnt = K;

    for (int u : order) {
        active[u] = 1;
        dsu[u] = u;
        sz[u] = 1;

        vector<int> roots;
        int r = u / M;
        int c = u % M;

        auto addNeighbor = [&](int v) {
            if (active[v]) {
                int rv = find(v);
                bool seen = false;
                for (int x : roots) {
                    if (x == rv) {
                        seen = true;
                        break;
                    }
                }
                if (!seen) roots.push_back(rv);
            }
        };

        if (r > 0) addNeighbor(u - M);
        if (r + 1 < N) addNeighbor(u + M);
        if (c > 0) addNeighbor(u - 1);
        if (c + 1 < M) addNeighbor(u + 1);

        if (roots.empty()) {
            compNode[u] = u;
        } else {
            int internal = nodeCnt++;
            val[internal] = P[u];
            sum[internal] = P[u];
            parent[u] = internal;
            children[internal].push_back(u);

            for (int rv : roots) {
                int child = compNode[rv];
                parent[child] = internal;
                children[internal].push_back(child);
                sum[internal] += sum[child];
            }

            for (int rv : roots) {
                unite(u, rv);
            }

            int root = find(u);
            compNode[root] = internal;
        }
    }

    int finalRoot = compNode[find(0)];

    vector<int> st;
    st.push_back(finalRoot);
    F[finalRoot] = finalRoot;

    while (!st.empty()) {
        int p = st.back();
        st.pop_back();

        for (int ch : children[p]) {
            if (val[p] <= sum[ch]) {
                F[ch] = F[p];
            } else {
                F[ch] = ch;
            }
            st.push_back(ch);
        }
    }

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            int id = i * M + j;
            if (j) cout << ' ';
            cout << sum[F[id]];
        }
        cout << '\n';
    }

    return 0;
}
